// Get data from all nodes
const geocodeData = $('Geocode Address').item.json;
const schoolsData = $('Get Schools').item.json;
const restaurantsData = $('Get Restaurants').item.json;
const transitData = $('Get Transit').item.json;

// Get coordinates
const coords = {
  lat: parseFloat(geocodeData.lat),
  lon: parseFloat(geocodeData.lon)
};

// Helper: Calculate distance in miles
function calcDistance(lat1, lon1, lat2, lon2) {
  const R = 3959; // Earth's radius in miles
  const dLat = (lat2 - lat1) * Math.PI / 180;
  const dLon = (lon2 - lon1) * Math.PI / 180;
  const a = 
    Math.sin(dLat/2) * Math.sin(dLat/2) +
    Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) *
    Math.sin(dLon/2) * Math.sin(dLon/2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
  return Math.round(R * c * 10) / 10; // Round to 1 decimal
}

// Process schools - get top 5 closest
const schools = (schoolsData.results || [])
  .filter(s => s.name)
  .map(s => ({
    name: s.name,
    rating: s.rating || 'N/A',
    distance: calcDistance(coords.lat, coords.lon, s.geometry.location.lat, s.geometry.location.lng),
    types: s.types
  }))
  .sort((a, b) => a.distance - b.distance)
  .slice(0, 5)
  .map(s => ({
    name: s.name,
    rating: s.rating,
    distance: s.distance + ' miles',
    type: s.types.includes('primary_school') ? 'Elementary' : 
          s.types.includes('secondary_school') ? 'High School' : 'School'
  }));

// Process restaurants - count and get top rated nearby
const restaurants = (restaurantsData.results || [])
  .filter(r => r.name && r.rating)
  .map(r => ({
    name: r.name,
    rating: r.rating,
    price_level: r.price_level || 0
  }));

const restaurantCount = restaurants.length;
const topRestaurants = restaurants
  .sort((a, b) => b.rating - a.rating)
  .slice(0, 5)
  .map(r => r.name);

// Process transit - get closest stations
const transit = (transitData.results || [])
  .filter(t => t.name)
  .map(t => ({
    name: t.name,
    distance: calcDistance(coords.lat, coords.lon, t.geometry.location.lat, t.geometry.location.lng)
  }))
  .sort((a, b) => a.distance - b.distance)
  .slice(0, 3)
  .map(t => ({
    name: t.name,
    distance: t.distance + ' miles'
  }));

// Return formatted neighborhood data
return {
  json: {
    schools: {
      count: schools.length,
      nearby: schools
    },
    restaurants: {
      count: restaurantCount,
      top_rated: topRestaurants
    },
    transportation: {
      transit_count: transit.length,
      nearby_stops: transit
    }
  }
};
